{
  "items": [
    {
      "title": "Saarland State Parliament Election 2017 (Landtagswahl 2017) – Official Election Results",
      "url_or_doi": "https://wahlergebnis.saarland.de/LTW_17/LINK_ZUR_DOWNLOAD_SEITE/",
      "justification": "Official election dataset published by Saarland's electoral authorities for the March 26, 2017 state parliamentary election. Provides downloadable election results, including votes received by political parties. Particularly useful for analyzing party performance, electoral competition, and voting patterns in Saarland during the 2010s."
    },
    {
      "title": "Saarland State Parliament Elections 1947–2022 – Historical Election Statistics",
      "url_or_doi": "https://www.saarland.de/stat/DE/_downloads/aktuelleTabellen/Wahlen/Landtagswahl/Landesergebnisse_seit_1947_ausgew%C3%A4hlte_Parteien.pdf?__blob=publicationFile&v=7",
      "justification": "Official historical election statistics from the Saarland Statistical Office. Includes results for the 2012 and 2017 state elections, with information on eligible voters, turnout, valid and invalid ballots, and party vote shares. Suitable for longitudinal comparisons of electoral behavior and political developments."
    },
    {
      "title": "Saarland State Parliament Election 2017 – Final Official Results by Municipality",
      "url_or_doi": "https://www.statistischebibliothek.de/mir/servlets/MCRFileNodeServlet/SLAusgabe_derivate_00000200/SL_Einzelschriften_129_%28Landtagswahl_2017_endg._Ergebnisse%29.pdf",
      "justification": "Official statistical publication containing the final results of the 2017 Saarland state election. Includes municipality-level election statistics, voter participation, and party results. Particularly valuable for geographical election analysis and comparisons between urban and rural municipalities."
    },
    {
      "title": "Saarland Elections – Statistical Information for the 2017 State Election",
      "url_or_doi": "https://www.statistischebibliothek.de/mir/servlets/MCRFileNodeServlet/SLAusgabe_derivate_00000523/SL_Einzelschriften_127_%28Informationen_zu_den_Wahlen_2017%29.pdf",
      "justification": "Official statistical publication providing historical election information for Saarland, including municipality-level results from the 2012 state election and earlier elections. Contains eligible-voter counts, turnout statistics, valid votes, and party-specific results. Useful for comparing electoral developments leading up to the 2017 election."
    },
    {
      "title": "Saarland State Parliament Election 2017 – Preliminary Results",
      "url_or_doi": "https://www.statistischebibliothek.de/mir/servlets/MCRFileNodeServlet/SLAusgabe_derivate_00000197/SL_Einzelschriften_128_%28Landtagswahl_2017_vorl._Ergebnisse%29.pdf",
      "justification": "Official preliminary results of the March 2017 Saarland state election. Contains electoral statistics organized by constituencies and municipalities, including eligible voters and party vote totals. Useful for examining election reporting and comparing preliminary results with final official figures."
    },
    {
      "title": "German Federal Election 2013 – Official Results for Saarland",
      "url_or_doi": "https://www.bundeswahlleiterin.de/bundestagswahlen/2013/ergebnisse/bund-99/land-10.html",
      "justification": "Official results from Germany's Federal Returning Officer for the September 22, 2013 federal election in Saarland. Provides party vote totals, vote percentages, and comparisons with previous elections. Useful for studying Saarland's electoral behavior in national elections and comparing federal and state voting patterns."
    },
    {
      "title": "Saarland Elections – Official Electoral Results Portal",
      "url_or_doi": "https://wahlergebnis.saarland.de/",
      "justification": "Official election results portal maintained by Saarland's electoral authorities and Statistical Office. Provides access to multiple elections held during the 2010s, including the 2017 state parliamentary election, 2017 federal election, 2019 European Parliament election, and 2019 municipal elections. Especially useful for researchers seeking comparable election results across different electoral levels."
    },
    {
      "title": "Saarland Municipal Elections 2019 – Official Election Results",
      "url_or_doi": "https://wahlergebnis.saarland.de/",
      "justification": "The official Saarland election portal includes results for the May 26, 2019 municipal elections, covering district council elections (Kreistagswahlen) and municipal council elections (Gemeinderatswahlen). These results are relevant for analyzing local political competition, geographical variation in party support, and electoral participation during the late 2010s."
    },
    {
      "title": "Saarbrücken State Parliament Elections 2012 and 2017 – Official City Results",
      "url_or_doi": "https://www.saarbruecken.de/rathaus/stadtpolitik/wahlen/ergebnisse_der_landtagswahl_2017",
      "justification": "Official election results published by the City of Saarbrücken. Provides downloadable documents covering the 2012 and 2017 state elections within Saarbrücken. Particularly useful for studying voting behavior in Saarland's capital and comparing electoral changes across election cycles."
    },
    {
      "title": "Saarbrücken Federal Elections 2013 and 2017 – Election Results",
      "url_or_doi": "https://www.saarbruecken.de/rathaus/stadtpolitik/wahlen/wahlergebnisse/ergebnisse_der_bundestagswahlen/ergebnisse_der_bundestagswahl_2017_fuer_saarbruecken",
      "justification": "Official municipal election results for the 2013 and 2017 German federal elections in Saarbrücken. Supports analysis of party preferences and electoral changes in Saarland's largest city, including comparisons between the two federal election cycles."
    },
    {
      "title": "Saarbrücken European Parliament and Municipal Elections 2014–2019",
      "url_or_doi": "https://www.saarbruecken.de/rathaus/stadtpolitik/wahlen/wahlergebnisse/ergebnisse_der_kommunalwahlen/heft_vor_den_kommunal_und_europawahlen_2019",
      "justification": "Official Saarbrücken municipal election resource containing results from the 2019 European Parliament and local elections, alongside historical results from 2014. Includes downloadable statistical documents and spreadsheet data. Suitable for examining local election outcomes, voter turnout, and changes in political preferences between 2014 and 2019."
    },
    {
      "title": "Saarland Statistical Yearbook 2015 – Historical Election Results",
      "url_or_doi": "https://www.statistischebibliothek.de/mir/servlets/MCRFileNodeServlet/SLAusgabe_derivate_00000194/SL_Jahrbuch_2015.pdf",
      "justification": "Official statistical yearbook containing historical election results for Saarland through 2014. Covers the 2012 state election, 2013 federal election, and 2014 European Parliament and municipal elections. Includes eligible voters, votes cast, valid votes, and political party results, making it useful for cross-election comparisons."
    },
    {
      "title": "Regional Election Statistics for Saarland – GovData Open Data Portal",
      "url_or_doi": "https://www.govdata.de/suche?sourceportal=1e17f560-2061-4219-a37d-61e2fce75336&state=10&type=dataset",
      "justification": "Germany's government open-data portal provides access to regional election datasets for Saarland. Its listings include state parliamentary election statistics by municipality through 2017, covering eligible voters, participation, valid votes, and party-specific results. Some datasets are available in CSV format, making them particularly suitable for quantitative analysis, statistical modeling, and integration with geographic or socioeconomic data."
    },
    {
      "title": "Saarland State Election Results 2012 and 2017 – Historical Electoral Database",
      "url_or_doi": "https://www.wahlrecht.de/ergebnisse/saarland.htm",
      "justification": "Historical election results database covering Saarland state parliamentary elections, including those held in 2012 and 2017. Provides party results and parliamentary seat distributions across election years. Useful as a supplementary source for comparing party performance and shifts in parliamentary representation during the 2010s."
    },
    {
      "title": "Wahl-O-Mat Archive – Saarland State Election 2017",
      "url_or_doi": "https://www.bpb.de/themen/wahl-o-mat/45817/wahl-o-mat-archiv-weitere-wahlen/",
      "justification": "Archive maintained by Germany's Federal Agency for Civic Education, offering downloadable archived Wahl-O-Mat materials for the March 26, 2017 Saarland state election. Relevant for researchers examining political party positions, election issues, and voter advice applications. Unlike official election-result datasets, this resource focuses on electoral information and party-position comparisons."
    }
  ]
}
